/bin/bash -lc "node --input-type=module <<'EOF'
import { execFileSync } from 'node:child_process';

const chars = \" "'!'"\\\"#"'$%&'"'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\\\]"'^_`abcdefghijklmnopqrstuvwxyz{|}~";
function randomString(length) {
  let output = '"'';
  for (let index = 0; index < length; index += 1) {
    output += chars[Math.floor(Math.random() * chars.length)];
  }
  return output;
}

for (let index = 0; index < 25; index += 1) {
  const key = randomString(16);
  const iv = randomString(16);
  const data = randomString(48);
  const args = ['--key', key, '--iv', iv, '--data', data];
  const py = execFileSync('/workspace/dataset/test17_executable', args, { encoding: 'utf8' });
  const js = execFileSync('node', ['/output/test17.mjs', ...args], { encoding: 'utf8' });
  if (py "'!== js) {
    console.error('"'Mismatch detected');
    console.error(JSON.stringify({ key, iv, data, py, js }, null, 2));
    process.exit(1);
  }
}

console.log('randomized verification passed');
EOF"

